  if (st === 'noir') return { bg: [220, 30, 8], sea: [215, 40, 16], seaHi: [205, 35, 28], land: [220, 20, 24], landHi: [210, 18, 38], grat: [200, 15, 58], major: [195, 25, 82], ice: [205, 10, 60], txt: [200, 15, 62], line: 0 };
