// ---- background plate ----
noStroke();
for (let r = 0; r < 5; r++) { const t = r / 4; fill(C.bg[0], C.bg[1], C.bg[2] * (1 - t * 0.5), 100); rect(0, 0, width, height * (1 - t) ); }
fill(C.bg[0], C.bg[1], C.bg[2]); rect(0, 0, width, height);

